--
-- Struktur dari tabel `transactions`
--

CREATE TABLE `transactions` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `tanggal` date NOT NULL,
  `periode` varchar(7) NOT NULL,
  `nominal` int(11) NOT NULL,
  `admin_fee` int(11) NOT NULL,
  `status` varchar(50) NOT NULL,
  `keterangan` text DEFAULT NULL,
  `rekening_tujuan` varchar(255) DEFAULT '',
  `rekening_tujuan_label` varchar(255) DEFAULT '',
  `created_at` datetime NOT NULL,
  `product` varchar(10) DEFAULT 'reg',
  `cancel_until` datetime DEFAULT NULL,
  `notified_onproses` int(11) DEFAULT 0,
  `urg_lock_until` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

